-- Adaptive assessment persistence for Prompt 11.
-- Assessment domain versions below are generated from ALGORITHM_VERSIONS and
-- pinned to the TypeScript registry by backend/test/assessment.unit.mjs.
-- Unreconciled declared/tested inputs are stored beside the policy result so a
-- future reconciliation version can replay historical sessions.
--
-- rollback:
--   DROP TABLE IF EXISTS praxis.assessment_decision;
--   DROP TABLE IF EXISTS praxis.assessment_response;
--   DROP TABLE IF EXISTS praxis.assessment_session;
--   DROP TABLE IF EXISTS praxis.assessment_item;

CREATE TABLE praxis.assessment_item (
  id uuid PRIMARY KEY,
  skill_id text NOT NULL
    REFERENCES praxis.skill(id) ON DELETE RESTRICT,
  target_level text NOT NULL CHECK (target_level IN ('L1', 'L2', 'L3')),
  sub_skill_id text NOT NULL CHECK (sub_skill_id IN (
    'sub_concepts_vocabulary',
    'sub_tool_workflow',
    'sub_result_interpretation',
    'sub_coordination_process',
    'sub_arbitrage'
  )),
  item_payload jsonb NOT NULL CHECK (
    jsonb_typeof(item_payload) = 'object'
    AND jsonb_typeof(item_payload -> 'options') = 'array'
    AND item_payload ? 'stemFr'
    AND item_payload ? 'keyOptionId'
  ),
  item_version text NOT NULL,
  status text NOT NULL CHECK (status IN ('draft', 'published', 'retired')),
  language text NOT NULL CHECK (language ~ '^[a-z]{2}(-[A-Z]{2})?$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX assessment_item_serving_idx
  ON praxis.assessment_item (skill_id, target_level, language, status);

CREATE TRIGGER assessment_item_touch_updated_at
BEFORE UPDATE ON praxis.assessment_item
FOR EACH ROW EXECUTE FUNCTION praxis.touch_updated_at();

CREATE TABLE praxis.assessment_session (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  learner_id uuid NOT NULL
    REFERENCES praxis.learner(id) ON DELETE CASCADE,
  skill_id text NOT NULL
    REFERENCES praxis.skill(id) ON DELETE RESTRICT,
  target_role_id text
    REFERENCES praxis.occupation(id) ON DELETE RESTRICT,
  status text NOT NULL DEFAULT 'started'
    CHECK (status IN ('started', 'in_progress', 'completed', 'abandoned')),
  rng_seed integer NOT NULL CHECK (rng_seed BETWEEN 0 AND 2147483647),
  algorithm_version text NOT NULL,
  inputs_hash text NOT NULL CHECK (inputs_hash ~ '^[a-f0-9]{64}$'),
  declared_level text CHECK (declared_level IN ('L1', 'L2', 'L3')),
  declared_confidence text CHECK (declared_confidence IN (
    'very_low', 'low', 'medium', 'medium_high', 'high'
  )),
  tested_level text CHECK (tested_level IN ('L1', 'L2', 'L3')),
  tested_confidence text CHECK (tested_confidence IN (
    'very_low', 'low', 'medium', 'medium_high', 'high'
  )),
  coverage_achieved boolean,
  final_level text CHECK (final_level IN ('L1', 'L2', 'L3')),
  reconciliation_confidence text CHECK (reconciliation_confidence IN (
    'very_low', 'low', 'medium', 'medium_high', 'high'
  )),
  reconciliation_status text CHECK (reconciliation_status IN (
    'reconciled_tested', 'reconciled_declared', 'declared_unverified',
    'insufficient_evidence', 'conflict_flagged', 'inconclusive_test'
  )),
  reconciliation_policy_version text,
  started_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  CHECK ((declared_level IS NULL) = (declared_confidence IS NULL)),
  CHECK ((tested_level IS NULL) = (tested_confidence IS NULL)),
  CHECK (completed_at IS NULL OR completed_at >= started_at),
  CHECK (
    status <> 'completed'
    OR (
      completed_at IS NOT NULL
      AND coverage_achieved IS NOT NULL
      AND reconciliation_status IS NOT NULL
      AND reconciliation_policy_version IS NOT NULL
    )
  )
);

CREATE INDEX assessment_session_learner_idx
  ON praxis.assessment_session (learner_id, started_at DESC);
CREATE INDEX assessment_session_active_idx
  ON praxis.assessment_session (learner_id, skill_id, started_at DESC)
  WHERE status IN ('started', 'in_progress');

CREATE TABLE praxis.assessment_response (
  session_id uuid NOT NULL
    REFERENCES praxis.assessment_session(id) ON DELETE CASCADE,
  item_id uuid NOT NULL
    REFERENCES praxis.assessment_item(id) ON DELETE RESTRICT,
  response_payload jsonb NOT NULL CHECK (jsonb_typeof(response_payload) = 'object'),
  correctness boolean NOT NULL,
  served_position smallint NOT NULL CHECK (served_position > 0),
  responded_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (session_id, item_id),
  UNIQUE (session_id, served_position)
);

CREATE TABLE praxis.assessment_decision (
  session_id uuid NOT NULL
    REFERENCES praxis.assessment_session(id) ON DELETE CASCADE,
  step smallint NOT NULL CHECK (step > 0),
  item_id uuid NOT NULL
    REFERENCES praxis.assessment_item(id) ON DELETE RESTRICT,
  target_level text NOT NULL CHECK (target_level IN ('L1', 'L2', 'L3')),
  log_likelihood_ratio numeric(12,8) NOT NULL,
  lower_boundary numeric(12,8) NOT NULL,
  upper_boundary numeric(12,8) NOT NULL,
  boundary_crossing text CHECK (boundary_crossing IN ('mastery', 'non_mastery')),
  terminal_decision text NOT NULL
    CHECK (terminal_decision IN ('mastery', 'non_mastery', 'undecided')),
  coverage_achieved boolean NOT NULL,
  algorithm_version text NOT NULL,
  inputs_hash text NOT NULL CHECK (inputs_hash ~ '^[a-f0-9]{64}$'),
  decided_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (session_id, step)
);

COMMENT ON TABLE praxis.assessment_item IS
  'Versioned item bank. Seed rows are explicitly uncalibrated engine fixtures and must not be represented as validated production items.';
COMMENT ON TABLE praxis.assessment_decision IS
  'Append-only per-response SPRT audit trace with computation provenance.';

